class ThreeDPrintCalculator extends HTMLElement {
  constructor() {
    super();
    this.storageKey = "ha-3d-print-calculator";
    this.legacyStorageKey = "ha-3d-print-calculator-v2";
    this.activeTab = "calculator";
    this.editingMaterialId = null;
    this.editingPrinterId = null;
    this.orderItems = [];
    this.hass = null;
    this._copyStatusTimer = null;
    this.defaults = {
      materials: [
        {id:"pla",name:"PLA",spoolWeight:1000,price:2200,stockGrams:0,stockSpools:0},
        {id:"pla-plus",name:"PLA+",spoolWeight:1000,price:2500,stockGrams:0,stockSpools:0},
        {id:"petg",name:"PETG",spoolWeight:1000,price:2400,stockGrams:0,stockSpools:0},
        {id:"abs",name:"ABS",spoolWeight:1000,price:2600,stockGrams:0,stockSpools:0},
        {id:"asa",name:"ASA",spoolWeight:1000,price:3200,stockGrams:0,stockSpools:0},
        {id:"tpu-95a",name:"TPU 95A",spoolWeight:1000,price:3300,stockGrams:0,stockSpools:0},
        {id:"tpu-85a",name:"TPU 85A",spoolWeight:1000,price:3500,stockGrams:0,stockSpools:0},
        {id:"pa",name:"PA",spoolWeight:1000,price:4200,stockGrams:0,stockSpools:0},
        {id:"pa-cf",name:"PA-CF",spoolWeight:1000,price:5500,stockGrams:0,stockSpools:0},
        {id:"pet-cf",name:"PET-CF",spoolWeight:1000,price:5000,stockGrams:0,stockSpools:0},
        {id:"pc",name:"PC",spoolWeight:1000,price:4500,stockGrams:0,stockSpools:0}
      ],
      printers:[{id:"x1c",name:"Bambu Lab X1C",electricity:2,depreciation:50,consumables:10}],
      settings:{waste:5,rounding:50,commercial:{retailMarkup:70,regularDiscount:15,urgentMarkup:30,minimumOrder:500,wholesaleTiers:[{minQuantity:2,maxQuantity:4,discount:5},{minQuantity:5,maxQuantity:9,discount:10},{minQuantity:10,maxQuantity:49,discount:20},{minQuantity:50,maxQuantity:null,discount:30}]}},
      calculator:{materialId:"tpu-95a",printerId:"x1c",weight:106,hours:2,minutes:11,quantity:1,packaging:0,postProcessing:0,labor:0,customerType:"retail",urgent:false},
      orders:[],
      history:[]
    };
    this.data=this.loadData();
  }
  connectedCallback(){this.render();}
  number(v,f=0){const n=Number(v);return Number.isFinite(n)?n:f;}
  money(v){return `${Math.round(this.number(v)).toLocaleString("ru-RU")} ₽`;}
  moneyExact(v){return `${this.number(v).toLocaleString("ru-RU",{minimumFractionDigits:2,maximumFractionDigits:2})} ₽`;}
  id(prefix="item"){return `${prefix}-${Date.now()}-${Math.random().toString(36).slice(2,8)}`;}
  clone(v){return structuredClone(v);}
  escape(v){return String(v??"").replaceAll("&","&amp;").replaceAll("<","&lt;").replaceAll(">","&gt;").replaceAll('"',"&quot;").replaceAll("'","&#039;");}
  mergeData(parsed={}){const d={...this.clone(this.defaults),...parsed};d.settings={...this.clone(this.defaults.settings),...(parsed.settings||{})};d.settings.commercial={...this.clone(this.defaults.settings.commercial),...(parsed.settings?.commercial||{})};d.calculator={...this.clone(this.defaults.calculator),...(parsed.calculator||{})};d.materials=Array.isArray(parsed.materials)?parsed.materials:this.clone(this.defaults.materials);d.printers=Array.isArray(parsed.printers)?parsed.printers:this.clone(this.defaults.printers);d.orders=Array.isArray(parsed.orders)?parsed.orders:[];d.history=Array.isArray(parsed.history)?parsed.history:[];d.materials=d.materials.map(m=>({stockGrams:0,stockSpools:0,...m}));if(!Array.isArray(d.settings.commercial.wholesaleTiers))d.settings.commercial.wholesaleTiers=this.clone(this.defaults.settings.commercial.wholesaleTiers);if(!["retail","regular","wholesale"].includes(d.calculator.customerType))d.calculator.customerType="retail";d.calculator.urgent=Boolean(d.calculator.urgent);return d;}
  loadData(){try{let saved=localStorage.getItem(this.storageKey);if(!saved){const legacy=localStorage.getItem(this.legacyStorageKey);if(legacy){saved=legacy;localStorage.setItem(this.storageKey,legacy);}}return saved?this.mergeData(JSON.parse(saved)):this.clone(this.defaults);}catch(e){console.error("3D Calculator load error",e);return this.clone(this.defaults);}}
  saveData(){localStorage.setItem(this.storageKey,JSON.stringify(this.data));this.dispatchEvent(new CustomEvent("three-d-print-calculator-changed",{bubbles:true,detail:{data:this.data,result:this.calculate()}}));}
  getMaterial(id=this.data.calculator.materialId){return this.data.materials.find(m=>m.id===id)||this.data.materials[0];}
  getPrinter(id=this.data.calculator.printerId){return this.data.printers.find(p=>p.id===id)||this.data.printers[0];}
  wholesaleDiscount(q){const t=(this.data.settings.commercial.wholesaleTiers||[]).find(x=>q>=this.number(x.minQuantity)&&q<=(x.maxQuantity==null?Infinity:this.number(x.maxQuantity)));return t?Math.max(0,this.number(t.discount)):0;}
  customerName(type=this.data.calculator.customerType){return type==="wholesale"?"Опт":type==="regular"?"Постоянный клиент":"Розница";}
  calculate(c=this.data.calculator){const m=this.getMaterial(c.materialId),p=this.getPrinter(c.printerId),s=this.data.settings,com=s.commercial;const weight=Math.max(0,this.number(c.weight)),q=Math.max(1,Math.round(this.number(c.quantity,1))),hours=Math.max(0,this.number(c.hours)),minutes=Math.min(59,Math.max(0,this.number(c.minutes))),time=hours+minutes/60;const waste=Math.max(0,this.number(s.waste)),effective=weight*(1+waste/100),totalWeight=effective*q,gram=m?.spoolWeight>0?this.number(m.price)/this.number(m.spoolWeight):0;const materialCost=totalWeight*gram,machineHourly=this.number(p?.electricity)+this.number(p?.depreciation)+this.number(p?.consumables),machineCost=time*machineHourly*q;const packaging=this.number(c.packaging)*q,post=this.number(c.postProcessing)*q,labor=this.number(c.labor)*q,cost=materialCost+machineCost+packaging+post+labor;const retailMarkup=Math.max(0,this.number(com.retailMarkup,70)),retailBase=cost*(1+retailMarkup/100);let discount=0,discountLabel="",beforeUrgent=retailBase;if(c.customerType==="regular"){discount=Math.max(0,this.number(com.regularDiscount));beforeUrgent=retailBase*(1-discount/100);discountLabel=`Постоянный клиент −${discount}%`;}if(c.customerType==="wholesale"){discount=this.wholesaleDiscount(q);beforeUrgent=retailBase*(1-discount/100);discountLabel=discount?`Оптовая скидка −${discount}%`:"Оптовая скидка не применяется";}const urgentMarkup=c.urgent?Math.max(0,this.number(com.urgentMarkup)):0,urgentCost=beforeUrgent*urgentMarkup/100,preMin=beforeUrgent+urgentCost,minOrder=Math.max(0,this.number(com.minimumOrder));let sale=Math.max(minOrder,preMin),rounding=Math.max(0,this.number(s.rounding));if(rounding)sale=Math.ceil(sale/rounding)*rounding;const profit=sale-cost;return {material:m,printer:p,weight,q,totalHours:time,effectiveWeightPerUnit:effective,totalEffectiveWeight:totalWeight,materialCost,machineCost,packagingCost:packaging,postProcessingCost:post,laborCost:labor,cost,costPerUnit:cost/q,retailMarkup,retailBasePrice:retailBase,customerType:this.customerName(c.customerType),discount,discountLabel,discountAmount:retailBase-beforeUrgent,urgentMarkup,urgentCost,priceBeforeMinimum:preMin,minimumOrder:minOrder,minimumApplied:preMin<minOrder,salePrice:sale,salePricePerUnit:sale/q,profit,margin:sale?(profit/sale)*100:0};}
  baseStyle(){return `<style>:host{display:block;height:100%;color:var(--primary-text-color);background:var(--primary-background-color);font-family:Arial,sans-serif}*{box-sizing:border-box}.page{max-width:1300px;margin:auto;padding:24px}.header{display:flex;justify-content:space-between;align-items:center;margin-bottom:20px}.title{font-size:30px;font-weight:800}.subtitle,.muted,label{color:var(--secondary-text-color)}.tabs{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:20px}button{border:0;border-radius:10px;padding:10px 14px;background:var(--secondary-background-color);color:var(--primary-text-color);cursor:pointer}button.primary,button.active{background:var(--primary-color);color:#fff}button.danger{color:var(--error-color)}button.small{padding:7px 9px;font-size:12px}.grid{display:grid;grid-template-columns:1.25fr .75fr;gap:20px}.card{background:var(--card-background-color,var(--secondary-background-color));border-radius:16px;padding:20px;margin-bottom:18px;box-shadow:var(--ha-card-box-shadow,0 2px 8px rgba(0,0,0,.12))}.form{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.full{grid-column:1/-1}.field{display:flex;flex-direction:column;gap:6px}input,select{width:100%;padding:10px;border:1px solid var(--divider-color);border-radius:9px;background:var(--primary-background-color);color:var(--primary-text-color)}input:focus,select:focus{outline:2px solid var(--primary-color);outline-offset:1px}.choice-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.choice{position:relative}.choice input{position:absolute;opacity:0;pointer-events:none}.choice label{display:block;cursor:pointer;padding:15px;border:1px solid var(--divider-color);border-radius:13px;background:var(--primary-background-color);color:var(--primary-text-color);font-size:14px;transition:.15s;min-height:76px}.choice label strong{display:block;font-size:15px;margin-bottom:5px}.choice label span{display:block;color:var(--secondary-text-color);font-size:12px;line-height:1.35}.choice input:checked+label{border-color:var(--primary-color);box-shadow:0 0 0 1px var(--primary-color),0 4px 14px rgba(0,0,0,.10);transform:translateY(-1px)}.urgent-choice{display:flex;align-items:center;gap:10px;padding:15px;margin-top:12px;border:1px solid var(--divider-color);border-radius:13px;cursor:pointer;background:var(--primary-background-color);transition:.15s}.urgent-choice:has(input:checked){border-color:var(--primary-color);box-shadow:0 0 0 1px var(--primary-color),0 4px 14px rgba(0,0,0,.10)}.urgent-choice input{width:auto}.result{position:sticky;top:15px}.big{text-align:center;font-size:42px;font-weight:900;margin:12px 0 22px}.row{display:flex;justify-content:space-between;gap:10px;padding:10px 0;border-bottom:1px solid var(--divider-color)}.row:last-child{border-bottom:0}.actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:16px}.summary{display:grid;grid-template-columns:repeat(2,1fr);gap:10px}.box{padding:14px;border-radius:11px;background:var(--primary-background-color)}.box b{font-size:19px}.client-price{padding:16px;border-radius:13px;background:var(--primary-background-color);margin-top:14px;text-align:center}.client-price .label{font-size:12px;color:var(--secondary-text-color)}.client-price b{display:block;font-size:24px;margin-top:4px}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:10px;border-bottom:1px solid var(--divider-color)}th{font-size:12px;color:var(--secondary-text-color)}.editor{margin-top:16px;padding-top:16px;border-top:1px solid var(--divider-color)}.notice{padding:12px;border-radius:10px;background:var(--primary-background-color);margin-top:10px}.list{display:grid;gap:10px}.item{padding:14px;border:1px solid var(--divider-color);border-radius:12px}.item-head{display:flex;justify-content:space-between;gap:10px}.profile{display:grid;grid-template-columns:1fr 120px 80px;gap:8px;align-items:center;margin-bottom:8px}.order-item{display:grid;grid-template-columns:1.4fr 90px 100px 100px auto;gap:8px;align-items:end;padding:12px;background:var(--primary-background-color);border-radius:10px;margin-bottom:8px}.check{display:flex;gap:8px;align-items:center}.check input{width:auto}.toast{position:fixed;right:20px;bottom:20px;padding:12px 16px;border-radius:10px;background:var(--primary-color);color:#fff;z-index:9999;opacity:0;pointer-events:none;transition:opacity .2s}.toast.show{opacity:1}@media(max-width:850px){.grid{grid-template-columns:1fr}.result{position:static}.form{grid-template-columns:1fr}.full{grid-column:auto}.choice-grid{grid-template-columns:1fr}.order-item{grid-template-columns:1fr 1fr}.profile{grid-template-columns:1fr}.page{padding:14px}.header{align-items:flex-start;gap:10px;flex-direction:column}}@media print{body *{visibility:hidden!important}#three-d-print-sheet,#three-d-print-sheet *{visibility:visible!important}#three-d-print-sheet{position:absolute;left:0;top:0;width:100%;padding:24px;background:#fff;color:#111}.no-print{display:none!important}}</style>`;}
  toast(msg){let t=this.querySelector(".toast");if(!t){t=document.createElement("div");t.className="toast";this.appendChild(t);}t.textContent=msg;t.classList.add("show");clearTimeout(this._toastTimer);this._toastTimer=setTimeout(()=>t.classList.remove("show"),1800);}
  showCopyStatus(text){const e=this.querySelector("#copy-status");if(!e)return;e.textContent=text;e.classList.add("show");clearTimeout(this._copyStatusTimer);this._copyStatusTimer=setTimeout(()=>e.classList.remove("show"),1800);}
  async copy(text){try{if(navigator.clipboard&&window.isSecureContext){await navigator.clipboard.writeText(text);this.showCopyStatus("✓ Скопировано");return true;}}catch(e){console.warn("Clipboard API failed",e);}try{const t=document.createElement("textarea");t.value=text;t.setAttribute("readonly","");t.style.position="fixed";t.style.left="-9999px";document.body.appendChild(t);t.focus();t.select();const ok=document.execCommand("copy");t.remove();this.showCopyStatus(ok?"✓ Скопировано":"⚠️ Не удалось скопировать");return ok;}catch(e){console.warn("Clipboard fallback failed",e);this.showCopyStatus("⚠️ Не удалось скопировать");return false;}}
  render(){const r=this.calculate();this.innerHTML=this.baseStyle()+`<div class="page"><div class="header"><div><div class="title">3D Калькулятор</div><div class="subtitle">Расчёт, заказы, материалы, принтеры и коммерческие цены</div></div><div class="muted">💾 данные сохраняются автоматически</div></div><div class="tabs">${[["calculator","🧮 Калькулятор"],["orders","📦 Заказы"],["materials","🧵 Материалы"],["printers","🖨 Принтеры"],["history","🕘 История"],["settings","⚙️ Настройки"]].map(x=>`<button class="${this.activeTab===x[0]?"active":""}" data-tab="${x[0]}">${x[1]}</button>`).join("")}</div><div id="content"></div><div class="toast"></div></div>`;this.querySelectorAll("[data-tab]").forEach(b=>b.onclick=()=>{this.activeTab=b.dataset.tab;this.render();});const c=this.querySelector("#content");if(this.activeTab==="calculator"){c.innerHTML=this.renderCalculator(r);this.bindCalculator();}if(this.activeTab==="orders"){c.innerHTML=this.renderOrders();this.bindOrders();}if(this.activeTab==="materials"){c.innerHTML=this.renderMaterials();this.bindMaterials();}if(this.activeTab==="printers"){c.innerHTML=this.renderPrinters();this.bindPrinters();}if(this.activeTab==="history"){c.innerHTML=this.renderHistory();this.bindHistory();}if(this.activeTab==="settings"){c.innerHTML=this.renderSettings();this.bindSettings();}}
  renderCalculator(r){const c=this.data.calculator;return `<div class="grid"><div><div class="card"><h2>Расчёт</h2><div class="form"><div class="field"><label>Материал</label><select id="material">${this.data.materials.map(m=>`<option value="${m.id}" ${m.id===c.materialId?"selected":""}>${this.escape(m.name)}</option>`).join("")}</select></div><div class="field"><label>Принтер</label><select id="printer">${this.data.printers.map(p=>`<option value="${p.id}" ${p.id===c.printerId?"selected":""}>${this.escape(p.name)}</option>`).join("")}</select></div><div class="field"><label>Вес одного изделия, г</label><input id="weight" type="number" min="0" step="0.1" value="${c.weight}"></div><div class="field"><label>Количество, шт.</label><input id="quantity" type="number" min="1" step="1" value="${c.quantity}"></div><div class="field"><label>Время, часы</label><input id="hours" type="number" min="0" step="1" value="${c.hours}"></div><div class="field"><label>Время, минуты</label><input id="minutes" type="number" min="0" max="59" step="1" value="${c.minutes}"></div><div class="field"><label>Упаковка за единицу, ₽</label><input id="packaging" type="number" min="0" step="0.01" value="${c.packaging}"></div><div class="field"><label>Постобработка за единицу, ₽</label><input id="postProcessing" type="number" min="0" step="0.01" value="${c.postProcessing}"></div><div class="field"><label>Работа за единицу, ₽</label><input id="labor" type="number" min="0" step="0.01" value="${c.labor}"></div><div class="field full"><label>Тип клиента</label><div class="choice-grid"><div class="choice"><input type="radio" name="customerType" id="customer-retail" value="retail" ${c.customerType==="retail"?"checked":""}><label for="customer-retail"><strong>🛍️ Розница</strong><span>Базовая наценка ${this.data.settings.commercial.retailMarkup}%</span></label></div><div class="choice"><input type="radio" name="customerType" id="customer-regular" value="regular" ${c.customerType==="regular"?"checked":""}><label for="customer-regular"><strong>⭐ Постоянный клиент</strong><span>Скидка ${this.data.settings.commercial.regularDiscount}%</span></label></div><div class="choice"><input type="radio" name="customerType" id="customer-wholesale" value="wholesale" ${c.customerType==="wholesale"?"checked":""}><label for="customer-wholesale"><strong>📦 Опт</strong><span>Скидка зависит от количества</span></label></div></div><label class="urgent-choice"><input id="urgent" type="checkbox" ${c.urgent?"checked":""}><span><b>⚡ Срочный заказ</b><br><span class="muted">Надбавка ${this.data.settings.commercial.urgentMarkup}%</span></span></label></div></div></div><div class="card"><h3>Расшифровка</h3><div class="row"><span>Материал</span><b>${this.money(r.materialCost)}</b></div><div class="row"><span>Принтер</span><b>${this.money(r.machineCost)}</b></div><div class="row"><span>Упаковка</span><b>${this.money(r.packagingCost)}</b></div><div class="row"><span>Постобработка</span><b>${this.money(r.postProcessingCost)}</b></div><div class="row"><span>Работа</span><b>${this.money(r.laborCost)}</b></div><div class="row"><span>Себестоимость</span><b>${this.money(r.cost)}</b></div></div></div><div class="result"><div class="card"><h2>Результат</h2><div class="big" id="sale-price">${this.money(r.salePrice)}</div><div class="summary"><div class="box"><span>Себестоимость</span><br><b id="cost">${this.money(r.cost)}</b></div><div class="box"><span>Прибыль</span><br><b id="profit">${this.money(r.profit)}</b></div><div class="box"><span>Цена/шт.</span><br><b id="sale-unit">${this.money(r.salePricePerUnit)}</b></div><div class="box"><span>Маржа</span><br><b id="margin">${r.margin.toFixed(1)}%</b></div></div><div class="client-price"><div class="label">Цена для клиента</div><b id="client-price-value">${this.money(r.salePrice)}</b></div><div id="price-details"><div class="row"><span>${this.escape(r.customerType)}</span><b>${this.money(r.retailBasePrice)}</b></div><div class="row"><span>${this.escape(r.discountLabel||"Без скидки")}</span><b>−${this.money(r.discountAmount)}</b></div><div class="row"><span>Срочность</span><b>${r.urgentMarkup?`+${r.urgentMarkup}%`:"Нет"}</b></div><div class="row"><span>Минимальный заказ</span><b>${this.money(r.minimumOrder)}</b></div></div><div class="actions"><button class="primary" id="save-calc">💾 Сохранить расчёт</button><button id="print-calc">🖨 Печать / PDF</button><button id="copy-calc">📋 Скопировать расчёт</button><button id="copy-client-price">📄 Цена клиенту</button></div><div id="copy-status" class="notice" aria-live="polite"></div></div></div></div>`;}
  updateResult(){const r=this.calculate();const set=(id,text)=>{const e=this.querySelector(`#${id}`);if(e)e.textContent=text;};set("sale-price",this.money(r.salePrice));set("client-price-value",this.money(r.salePrice));set("cost",this.money(r.cost));set("profit",this.money(r.profit));set("sale-unit",this.money(r.salePricePerUnit));set("margin",`${r.margin.toFixed(1)}%`);const d=this.querySelector("#price-details");if(d)d.innerHTML=`<div class="row"><span>${this.escape(r.customerType)}</span><b>${this.money(r.retailBasePrice)}</b></div><div class="row"><span>${this.escape(r.discountLabel||"Без скидки")}</span><b>−${this.money(r.discountAmount)}</b></div><div class="row"><span>Срочность</span><b>${r.urgentMarkup?`+${r.urgentMarkup}%`:"Нет"}</b></div><div class="row"><span>Минимальный заказ</span><b>${this.money(r.minimumOrder)}</b></div>`;}
  bindCalculator(){const numeric=["weight","quantity","hours","minutes","packaging","postProcessing","labor"];numeric.forEach(id=>{const el=this.querySelector(`#${id}`);if(!el)return;el.addEventListener("input",()=>{this.data.calculator[id]=el.value;this.saveData();this.updateResult();});el.addEventListener("change",()=>{this.data.calculator[id]=el.value;this.saveData();this.updateResult();});});const m=this.querySelector("#material"),p=this.querySelector("#printer"),u=this.querySelector("#urgent");m.onchange=()=>{this.data.calculator.materialId=m.value;this.saveData();this.updateResult();};p.onchange=()=>{this.data.calculator.printerId=p.value;this.saveData();this.updateResult();};this.querySelectorAll("input[name=customerType]").forEach(e=>e.onchange=()=>{this.data.calculator.customerType=e.value;this.saveData();this.render();});u.onchange=()=>{this.data.calculator.urgent=u.checked;this.saveData();this.updateResult();};this.querySelector("#save-calc").onclick=()=>this.saveCalculation();this.querySelector("#print-calc").onclick=()=>this.printCalculation(this.calculate());this.querySelector("#copy-calc").onclick=()=>this.copy(this.textForResult(this.calculate()));this.querySelector("#copy-client-price").onclick=()=>this.copy(this.textForClient(this.calculate()));}
  saveCalculation(){const r=this.calculate();const entry={id:this.id("history"),createdAt:new Date().toISOString(),calculator:this.clone(this.data.calculator),result:{cost:r.cost,salePrice:r.salePrice,profit:r.profit,margin:r.margin,materialName:r.material?.name||"",printerName:r.printer?.name||""}};this.data.history=[entry,...this.data.history].slice(0,200);this.saveData();this.toast("Расчёт сохранён в истории");}
  textForResult(r){return `Расчёт 3D-печати\n\nМатериал: ${r.material?.name||""}\nПринтер: ${r.printer?.name||""}\nВес: ${r.weight} г\nКоличество: ${r.q}\nСебестоимость: ${this.money(r.cost)}\nЦена: ${this.money(r.salePrice)}\nПрибыль: ${this.money(r.profit)}\nМаржа: ${r.margin.toFixed(1)}%`;}
  textForClient(r){return `Расчёт 3D-печати\n\nМатериал: ${r.material?.name||""}\nКоличество: ${r.q} шт.\nВремя изготовления: ${this.data.calculator.hours} ч ${this.data.calculator.minutes} мин\n\nСтоимость заказа: ${this.money(r.salePrice)}\nСтоимость одного изделия: ${this.money(r.salePricePerUnit)}`;}
  renderOrders(){const o=this.data.orders;return `<div class="card"><div class="item-head"><h2>Заказы</h2><button class="primary" id="new-order">＋ Новый заказ</button></div>${o.length?`<div class="list">${o.map(x=>`<div class="item"><div class="item-head"><b>${this.escape(x.client||"Без клиента")}</b><span>${new Date(x.createdAt).toLocaleString("ru-RU")}</span></div><div class="row"><span>${x.items.length} позиции</span><b>${this.money(x.totalPrice)}</b></div><div class="row"><span>Себестоимость</span><b>${this.money(x.totalCost)}</b></div><div class="row"><span>Прибыль</span><b>${this.money(x.profit)}</b></div><div class="actions"><button data-order-open="${x.id}">Открыть</button><button data-order-print="${x.id}">Печать</button><button class="danger" data-order-delete="${x.id}">Удалить</button></div></div>`).join("")}</div>`:`<div class="notice">Заказов пока нет.</div>`}<div id="order-editor"></div></div>`;}
  bindOrders(){this.querySelector("#new-order").onclick=()=>{this.orderItems=[this.makeOrderItem(),this.makeOrderItem()];this.renderOrderEditor();};this.querySelectorAll("[data-order-delete]").forEach(b=>b.onclick=()=>{this.data.orders=this.data.orders.filter(x=>x.id!==b.dataset.orderDelete);this.saveData();this.render();});this.querySelectorAll("[data-order-open]").forEach(b=>b.onclick=()=>{const o=this.data.orders.find(x=>x.id===b.dataset.orderOpen);if(o){this.orderItems=this.clone(o.items);this.renderOrderEditor(o);}});this.querySelectorAll("[data-order-print]").forEach(b=>b.onclick=()=>{const o=this.data.orders.find(x=>x.id===b.dataset.orderPrint);if(o)this.printOrder(o);});}
  makeOrderItem(){const c=this.data.calculator;const r=this.calculate(c);return {id:this.id("oi"),name:"",quantity:Math.max(1,this.number(c.quantity,1)),materialId:c.materialId,printerId:c.printerId,weight:this.number(c.weight),hours:this.number(c.hours),minutes:this.number(c.minutes),cost:r.cost,salePrice:r.salePrice,profit:r.profit};}
  renderOrderEditor(order=null){const host=this.querySelector("#order-editor");if(!host)return;host.innerHTML=`<div class="editor"><h3>${order?"Редактирование заказа":"Новый заказ"}</h3><div class="field"><label>Клиент</label><input id="order-client" value="${this.escape(order?.client||"")}" placeholder="Имя / компания"></div><div class="actions"><button id="add-order-item">＋ Добавить позицию</button></div><div id="order-items">${this.orderItems.map((x,i)=>this.renderOrderItem(x,i)).join("")}</div><div id="order-summary" class="notice"></div><div class="actions"><button class="primary" id="save-order">💾 Сохранить заказ</button><button id="cancel-order">Отмена</button></div></div>`;this.bindOrderEditor(order);this.updateOrderSummary();}
  renderOrderItem(x,i){return `<div class="order-item" data-oi="${x.id}"><div class="field"><label>Позиция ${i+1}</label><input data-field="name" value="${this.escape(x.name)}" placeholder="Название изделия"></div><div class="field"><label>Количество</label><input data-field="quantity" type="number" min="1" step="1" value="${x.quantity}"></div><div class="field"><label>Материал</label><select data-field="materialId">${this.data.materials.map(m=>`<option value="${m.id}" ${m.id===x.materialId?"selected":""}>${this.escape(m.name)}</option>`).join("")}</select></div><div class="field"><label>Принтер</label><select data-field="printerId">${this.data.printers.map(p=>`<option value="${p.id}" ${p.id===x.printerId?"selected":""}>${this.escape(p.name)}</option>`).join("")}</select></div><button class="danger" data-remove-item="${x.id}">✕</button></div>`;}
  recalcOrderItem(x){const c={...this.data.calculator,materialId:x.materialId,printerId:x.printerId,weight:x.weight,quantity:x.quantity,hours:x.hours,minutes:x.minutes};const r=this.calculate(c);x.cost=r.cost;x.salePrice=r.salePrice;x.profit=r.profit;}
  bindOrderEditor(order){this.querySelector("#add-order-item").onclick=()=>{this.orderItems.push(this.makeOrderItem());this.renderOrderEditor(order);};this.querySelector("#cancel-order").onclick=()=>{this.orderItems=[];this.renderOrderEditor(null);};this.querySelectorAll("[data-remove-item]").forEach(b=>b.onclick=()=>{if(this.orderItems.length<=2){this.toast("Минимум 2 позиции");return;}this.orderItems=this.orderItems.filter(x=>x.id!==b.dataset.removeItem);this.renderOrderEditor(order);});this.querySelectorAll("[data-oi]").forEach(row=>{row.querySelectorAll("[data-field]").forEach(el=>el.addEventListener("input",()=>{const x=this.orderItems.find(i=>i.id===row.dataset.oi);if(!x)return;x[el.dataset.field]=el.value;if(el.dataset.field!=="name")this.recalcOrderItem(x);this.updateOrderSummary();}));});this.querySelector("#save-order").onclick=()=>{if(this.orderItems.length<2){this.toast("Добавьте минимум 2 позиции");return;}const client=this.querySelector("#order-client").value.trim();if(!client){this.toast("Укажите клиента");return;}this.orderItems.forEach(x=>this.recalcOrderItem(x));const totalCost=this.orderItems.reduce((a,x)=>a+this.number(x.cost),0),totalPrice=this.orderItems.reduce((a,x)=>a+this.number(x.salePrice),0);const existing=order?this.data.orders.find(x=>x.id===order.id):null;const obj={id:existing?.id||this.id("order"),createdAt:existing?.createdAt||new Date().toISOString(),client,items:this.clone(this.orderItems),totalCost,totalPrice,profit:totalPrice-totalCost};if(existing)Object.assign(existing,obj);else this.data.orders=[obj,...this.data.orders];this.saveData();this.orderItems=[];this.toast("Заказ сохранён");this.render();};}
  updateOrderSummary(){const e=this.querySelector("#order-summary");if(!e)return;const cost=this.orderItems.reduce((a,x)=>a+this.number(x.cost),0),price=this.orderItems.reduce((a,x)=>a+this.number(x.salePrice),0);e.innerHTML=`<b>Итого:</b> себестоимость ${this.money(cost)} · цена ${this.money(price)} · прибыль ${this.money(price-cost)}`;}
  renderMaterials(){return `<div class="card"><div class="item-head"><h2>Материалы</h2><button class="primary" id="add-material">＋ Добавить</button></div><table><thead><tr><th>Материал</th><th>Катушка, г</th><th>Цена</th><th>Остаток, г</th><th></th></tr></thead><tbody>${this.data.materials.map(m=>`<tr><td>${this.escape(m.name)}</td><td>${m.spoolWeight}</td><td>${this.money(m.price)}</td><td>${m.stockGrams||0}</td><td><button data-edit-material="${m.id}">Изменить</button> <button class="danger" data-delete-material="${m.id}">Удалить</button></td></tr>`).join("")}</tbody></table><div id="material-editor"></div></div>`;}
  bindMaterials(){this.querySelector("#add-material").onclick=()=>this.showMaterialEditor();this.querySelectorAll("[data-edit-material]").forEach(b=>b.onclick=()=>this.showMaterialEditor(this.data.materials.find(m=>m.id===b.dataset.editMaterial)));this.querySelectorAll("[data-delete-material]").forEach(b=>b.onclick=()=>{if(this.data.materials.length<=1){this.toast("Нужен хотя бы один материал");return;}this.data.materials=this.data.materials.filter(m=>m.id!==b.dataset.deleteMaterial);this.saveData();this.render();});}
  showMaterialEditor(m=null){const e=this.querySelector("#material-editor");e.innerHTML=`<div class="editor"><h3>${m?"Изменить материал":"Новый материал"}</h3><div class="form"><div class="field"><label>Название</label><input id="me-name" value="${this.escape(m?.name||"")}"></div><div class="field"><label>Вес катушки, г</label><input id="me-weight" type="number" min="1" value="${m?.spoolWeight||1000}"></div><div class="field"><label>Цена катушки, ₽</label><input id="me-price" type="number" min="0" step="0.01" value="${m?.price||0}"></div><div class="field"><label>Остаток, г</label><input id="me-stock" type="number" min="0" value="${m?.stockGrams||0}"></div></div><div class="actions"><button class="primary" id="me-save">Сохранить</button><button id="me-cancel">Отмена</button></div></div>`;this.querySelector("#me-save").onclick=()=>{const obj={id:m?.id||this.id("mat"),name:this.querySelector("#me-name").value.trim(),spoolWeight:this.number(this.querySelector("#me-weight").value,1000),price:this.number(this.querySelector("#me-price").value),stockGrams:this.number(this.querySelector("#me-stock").value),stockSpools:m?.stockSpools||0};if(!obj.name){this.toast("Введите название");return;}if(m)Object.assign(m,obj);else this.data.materials.push(obj);this.saveData();this.render();};this.querySelector("#me-cancel").onclick=()=>this.render();}
  renderPrinters(){return `<div class="card"><div class="item-head"><h2>Принтеры</h2><button class="primary" id="add-printer">＋ Добавить</button></div><table><thead><tr><th>Принтер</th><th>Электроэнергия/ч</th><th>Амортизация/ч</th><th>Расходники/ч</th><th></th></tr></thead><tbody>${this.data.printers.map(p=>`<tr><td>${this.escape(p.name)}</td><td>${p.electricity} ₽</td><td>${p.depreciation} ₽</td><td>${p.consumables} ₽</td><td><button data-edit-printer="${p.id}">Изменить</button> <button class="danger" data-delete-printer="${p.id}">Удалить</button></td></tr>`).join("")}</tbody></table><div id="printer-editor"></div></div>`;}
  bindPrinters(){this.querySelector("#add-printer").onclick=()=>this.showPrinterEditor();this.querySelectorAll("[data-edit-printer]").forEach(b=>b.onclick=()=>this.showPrinterEditor(this.data.printers.find(p=>p.id===b.dataset.editPrinter)));this.querySelectorAll("[data-delete-printer]").forEach(b=>b.onclick=()=>{if(this.data.printers.length<=1){this.toast("Нужен хотя бы один принтер");return;}this.data.printers=this.data.printers.filter(p=>p.id!==b.dataset.deletePrinter);this.saveData();this.render();});}
  showPrinterEditor(p=null){const e=this.querySelector("#printer-editor");e.innerHTML=`<div class="editor"><h3>${p?"Изменить принтер":"Новый принтер"}</h3><div class="form"><div class="field"><label>Название</label><input id="pe-name" value="${this.escape(p?.name||"")}"></div><div class="field"><label>Электроэнергия, ₽/ч</label><input id="pe-electricity" type="number" min="0" step="0.01" value="${p?.electricity||0}"></div><div class="field"><label>Амортизация, ₽/ч</label><input id="pe-depreciation" type="number" min="0" step="0.01" value="${p?.depreciation||0}"></div><div class="field"><label>Расходники, ₽/ч</label><input id="pe-consumables" type="number" min="0" step="0.01" value="${p?.consumables||0}"></div></div><div class="actions"><button class="primary" id="pe-save">Сохранить</button><button id="pe-cancel">Отмена</button></div></div>`;this.querySelector("#pe-save").onclick=()=>{const obj={id:p?.id||this.id("printer"),name:this.querySelector("#pe-name").value.trim(),electricity:this.number(this.querySelector("#pe-electricity").value),depreciation:this.number(this.querySelector("#pe-depreciation").value),consumables:this.number(this.querySelector("#pe-consumables").value)};if(!obj.name){this.toast("Введите название");return;}if(p)Object.assign(p,obj);else this.data.printers.push(obj);this.saveData();this.render();};this.querySelector("#pe-cancel").onclick=()=>this.render();}
  renderHistory(){return `<div class="card"><div class="item-head"><h2>История расчётов</h2><button class="danger" id="clear-history">Очистить</button></div>${this.data.history.length?`<div class="list">${this.data.history.map(x=>`<div class="item"><div class="item-head"><b>${this.escape(x.result.materialName||"Расчёт")}</b><span>${new Date(x.createdAt).toLocaleString("ru-RU")}</span></div><div class="row"><span>Принтер / количество</span><b>${this.escape(x.result.printerName||"")} / ${x.calculator.quantity}</b></div><div class="row"><span>Себестоимость</span><b>${this.money(x.result.cost)}</b></div><div class="row"><span>Цена / прибыль</span><b>${this.money(x.result.salePrice)} / ${this.money(x.result.profit)}</b></div><div class="actions"><button data-history-use="${x.id}">Повторить</button><button data-history-print="${x.id}">Печать</button><button class="danger" data-history-delete="${x.id}">Удалить</button></div></div>`).join("")}</div>`:`<div class="notice">История пуста. Сохраните расчёт из калькулятора.</div>`}</div>`;}
  bindHistory(){this.querySelector("#clear-history").onclick=()=>{if(confirm("Удалить всю историю?")){this.data.history=[];this.saveData();this.render();}};this.querySelectorAll("[data-history-use]").forEach(b=>b.onclick=()=>{const x=this.data.history.find(i=>i.id===b.dataset.historyUse);if(x){this.data.calculator=this.clone(x.calculator);this.saveData();this.activeTab="calculator";this.render();}});this.querySelectorAll("[data-history-delete]").forEach(b=>b.onclick=()=>{this.data.history=this.data.history.filter(x=>x.id!==b.dataset.historyDelete);this.saveData();this.render();});this.querySelectorAll("[data-history-print]").forEach(b=>b.onclick=()=>{const x=this.data.history.find(i=>i.id===b.dataset.historyPrint);if(x)this.printCalculation(this.calculate(x.calculator));});}
  renderSettings(){const s=this.data.settings,com=s.commercial;return `<div class="card"><h2>Настройки</h2><div class="form"><div class="field"><label>Отходы, %</label><input id="set-waste" type="number" min="0" step="0.1" value="${s.waste}"></div><div class="field"><label>Округление цены, ₽</label><input id="set-rounding" type="number" min="0" step="1" value="${s.rounding}"></div><div class="field"><label>Наценка розница, %</label><input id="set-retail" type="number" min="0" step="0.1" value="${com.retailMarkup}"></div><div class="field"><label>Скидка постоянного клиента, %</label><input id="set-regular" type="number" min="0" step="0.1" value="${com.regularDiscount}"></div><div class="field"><label>Наценка срочности, %</label><input id="set-urgent" type="number" min="0" step="0.1" value="${com.urgentMarkup}"></div><div class="field"><label>Минимальный заказ, ₽</label><input id="set-min" type="number" min="0" step="1" value="${com.minimumOrder}"></div></div><div class="actions"><button class="primary" id="save-settings">Сохранить настройки</button><button id="export-json">⬇️ Экспорт JSON</button><button id="import-json">⬆️ Импорт JSON</button><button id="reset-data" class="danger">Сбросить всё</button><input id="json-file" type="file" accept="application/json,.json" hidden></div><div class="notice">Экспорт включает материалы, принтеры, настройки, историю и сохранённые заказы.</div></div>`;}
  bindSettings(){this.querySelector("#save-settings").onclick=()=>{this.data.settings.waste=this.number(this.querySelector("#set-waste").value);this.data.settings.rounding=this.number(this.querySelector("#set-rounding").value);this.data.settings.commercial.retailMarkup=this.number(this.querySelector("#set-retail").value);this.data.settings.commercial.regularDiscount=this.number(this.querySelector("#set-regular").value);this.data.settings.commercial.urgentMarkup=this.number(this.querySelector("#set-urgent").value);this.data.settings.commercial.minimumOrder=this.number(this.querySelector("#set-min").value);this.saveData();this.toast("Настройки сохранены");};this.querySelector("#export-json").onclick=()=>this.exportJSON();this.querySelector("#import-json").onclick=()=>this.querySelector("#json-file").click();this.querySelector("#json-file").onchange=e=>{const f=e.target.files?.[0];if(f)this.importJSON(f);};this.querySelector("#reset-data").onclick=()=>{if(confirm("Удалить все данные и вернуть значения по умолчанию?")){this.data=this.clone(this.defaults);this.saveData();this.render();}};}
  exportJSON(){const blob=new Blob([JSON.stringify(this.data,null,2)],{type:"application/json;charset=utf-8"}),url=URL.createObjectURL(blob),a=document.createElement("a");a.href=url;a.download=`3d-print-calculator-${new Date().toISOString().slice(0,10)}.json`;document.body.appendChild(a);a.click();a.remove();URL.revokeObjectURL(url);this.toast("JSON экспортирован");}
  importJSON(file){const reader=new FileReader();reader.onload=()=>{try{const parsed=JSON.parse(reader.result);if(!parsed||typeof parsed!=="object")throw new Error("Invalid JSON");this.data=this.mergeData(parsed);this.saveData();this.render();this.toast("JSON импортирован");}catch(e){console.error("JSON import error",e);this.toast("Ошибка импорта JSON");}};reader.readAsText(file);}
  printCalculation(r){const sheet=this.makePrintSheet(`<h1>Расчёт 3D печати</h1><p>${new Date().toLocaleString("ru-RU")}</p><table><tr><td>Материал</td><td>${this.escape(r.material?.name||"")}</td></tr><tr><td>Принтер</td><td>${this.escape(r.printer?.name||"")}</td></tr><tr><td>Вес / количество</td><td>${r.weight} г / ${r.q}</td></tr><tr><td>Себестоимость</td><td>${this.money(r.cost)}</td></tr><tr><td>Цена</td><td>${this.money(r.salePrice)}</td></tr><tr><td>Прибыль</td><td>${this.money(r.profit)}</td></tr><tr><td>Маржа</td><td>${r.margin.toFixed(1)}%</td></tr></table>`);this.openPrint(sheet);}
  printOrder(o){const rows=o.items.map((x,i)=>`<tr><td>${i+1}</td><td>${this.escape(x.name||"Изделие")}</td><td>${x.quantity}</td><td>${this.money(x.cost)}</td><td>${this.money(x.salePrice)}</td><td>${this.money(x.profit)}</td></tr>`).join("");const sheet=this.makePrintSheet(`<h1>Заказ</h1><p>Клиент: <b>${this.escape(o.client)}</b></p><p>${new Date(o.createdAt).toLocaleString("ru-RU")}</p><table><tr><th>#</th><th>Позиция</th><th>Кол.</th><th>Себестоимость</th><th>Цена</th><th>Прибыль</th></tr>${rows}<tr><th colspan="3">Итого</th><th>${this.money(o.totalCost)}</th><th>${this.money(o.totalPrice)}</th><th>${this.money(o.profit)}</th></tr></table>`);this.openPrint(sheet);}
  makePrintSheet(html){return `<div id="three-d-print-sheet">${html}</div>`;}
  openPrint(html){const w=window.open("","_blank","noopener,noreferrer");if(!w){this.toast("Разрешите всплывающие окна для печати");return;}w.document.write(`<!doctype html><html><head><meta charset="utf-8"><title>3D печать</title><style>body{font-family:Arial,sans-serif;padding:30px;color:#111}table{width:100%;border-collapse:collapse}td,th{padding:9px;border:1px solid #ccc;text-align:left}h1{margin-top:0}@media print{body{padding:0}}</style></head><body>${html.replace('id="three-d-print-sheet"','')}</body></html>`);w.document.close();w.focus();setTimeout(()=>w.print(),150);}
}
customElements.define("three-d-print-calculator",ThreeDPrintCalculator);

// === 3D CALCULATOR UI ENHANCEMENTS BUNDLE START ===
const Calculator=customElements.get("three-d-print-calculator");
if(!Calculator)throw new Error("3D calculator main component was not registered");
const p=Calculator.prototype;
const originalBaseStyle=p.baseStyle;
const originalRenderSettings=p.renderSettings;
const originalBindSettings=p.bindSettings;
const originalCalculate=p.calculate;
const num=(v,f=0)=>{const n=Number(v);return Number.isFinite(n)?n:f;};

function migrate(c,s){
  const q=Math.max(1,Math.round(num(c.quantity,1)));
  if(!Object.prototype.hasOwnProperty.call(c,"packagingQty"))c.packagingQty=0;
  if(!Object.prototype.hasOwnProperty.call(c,"postProcessingQty"))c.postProcessingQty=q;
  c.packagingQty=Math.max(0,Math.round(num(c.packagingQty,0)));
  c.postProcessingQty=Math.max(0,Math.round(num(c.postProcessingQty,q)));
  if(!s.costs||typeof s.costs!=="object")s.costs={};
  if(s.costsVersion!==2){s.costs={packaging:500,postProcessing:300};s.costsVersion=2;}
  delete s.costs.labor;
  s.costs.packaging=Math.max(0,num(s.costs.packaging,500));
  s.costs.postProcessing=Math.max(0,num(s.costs.postProcessing,300));
  return q;
}

p.baseStyle=function(){const css=originalBaseStyle.call(this);const extra=`<style>
.result-card{overflow:hidden}.price-hero{padding:18px;border-radius:14px;background:linear-gradient(135deg,var(--primary-color),var(--accent-color,var(--primary-color)));color:#fff;text-align:center;margin:0 0 14px}.price-hero .eyebrow{font-size:11px;opacity:.82;text-transform:uppercase;letter-spacing:.07em}.price-hero .price{font-size:36px;font-weight:800;line-height:1.05;margin:7px 0}.price-hero .per-unit{font-size:13px;opacity:.9}.result-section{padding:13px 0;border-top:1px solid var(--divider-color)}.result-section h3{margin:0 0 9px;font-size:14px}.cost-list,.commercial{display:grid;gap:3px}.cost-line,.commercial-line{display:flex;justify-content:space-between;gap:12px;padding:7px 0}.cost-line .meta{color:var(--secondary-text-color);font-size:11px}.cost-total{display:flex;justify-content:space-between;padding:11px;margin-top:5px;border-radius:9px;background:var(--primary-background-color);font-weight:800}.commercial-line .value{font-weight:700}.explain{padding:10px 11px;border-radius:9px;background:var(--primary-background-color);color:var(--secondary-text-color);font-size:11px;line-height:1.4;margin-top:7px}.field-hint{font-size:11px;color:var(--secondary-text-color);line-height:1.3;margin-top:-2px}.copy-grid{display:grid;grid-template-columns:1fr 1fr;gap:8px}.copy-grid button{width:100%}.profit-positive{font-size:19px;font-weight:800}.minimum-note{padding:9px;border-radius:9px;background:var(--primary-background-color);font-size:11px;margin-top:7px}.copy-grid+#copy-status{display:none}.copy-grid+#copy-status.show{display:block}.settings-costs{grid-column:1/-1;padding:14px;border:1px solid var(--divider-color);border-radius:12px;background:var(--primary-background-color);margin-top:12px}.settings-costs h3{margin:0 0 5px;font-size:15px}.settings-costs .hint{color:var(--secondary-text-color);font-size:11px;line-height:1.4;margin-bottom:10px}.settings-cost-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}@media(max-width:850px){.copy-grid{grid-template-columns:1fr}.settings-cost-grid{grid-template-columns:1fr}}
</style>`;return css.replace("</style>",extra.replace("<style>","").replace("</style>","")+"</style>");};

p.calculate=function(c=this.data.calculator){const q=migrate(c,this.data.settings);const s=this.data.settings,ratePack=num(s.costs.packaging,500),ratePost=num(s.costs.postProcessing,300);const packQty=Math.min(q,Math.max(0,Math.round(num(c.packagingQty,0)))),postQty=Math.min(q,Math.max(0,Math.round(num(c.postProcessingQty,q))));const adapted={...c,packaging:ratePack*packQty/q,postProcessing:ratePost*postQty/q,labor:0};const r=originalCalculate.call(this,adapted);r.packagingRate=ratePack;r.postProcessingRate=ratePost;r.packagingQty=packQty;r.postProcessingQty=postQty;r.packagingCost=ratePack*packQty;r.postProcessingCost=ratePost*postQty;r.laborCost=0;r.cost=r.materialCost+r.machineCost+r.packagingCost+r.postProcessingCost;r.costPerUnit=r.cost/r.q;r.retailBasePrice=r.cost*(1+r.retailMarkup/100);let discount=0,label="",before=r.retailBasePrice;if(c.customerType==="regular"){discount=Math.max(0,num(s.commercial.regularDiscount));before=r.retailBasePrice*(1-discount/100);label=`Постоянный клиент −${discount}%`;}if(c.customerType==="wholesale"){discount=this.wholesaleDiscount(r.q);before=r.retailBasePrice*(1-discount/100);label=discount?`Оптовая скидка −${discount}%`:"Оптовая скидка не применяется";}const urgentMarkup=c.urgent?Math.max(0,num(s.commercial.urgentMarkup)):0,urgentCost=before*urgentMarkup/100,preMin=before+urgentCost,minOrder=Math.max(0,num(s.commercial.minimumOrder));let sale=Math.max(minOrder,preMin);const rounding=Math.max(0,num(s.rounding));if(rounding)sale=Math.ceil(sale/rounding)*rounding;r.discount=discount;r.discountLabel=label;r.discountAmount=r.retailBasePrice-before;r.urgentMarkup=urgentMarkup;r.urgentCost=urgentCost;r.priceBeforeMinimum=preMin;r.minimumOrder=minOrder;r.minimumApplied=preMin<minOrder;r.salePrice=sale;r.salePricePerUnit=sale/r.q;r.profit=sale-r.cost;r.margin=sale?(r.profit/sale)*100:0;return r;};

p.renderCalculator=function(r){const c=this.data.calculator,q=migrate(c,this.data.settings),s=this.data.settings;const pack=Math.min(q,Math.max(0,Math.round(num(c.packagingQty,0)))),post=Math.min(q,Math.max(0,Math.round(num(c.postProcessingQty,q))));return `<div class="grid"><div><div class="card"><h2>Расчёт</h2><div class="form"><div class="field"><label>Материал</label><select id="material">${this.data.materials.map(m=>`<option value="${m.id}" ${m.id===c.materialId?"selected":""}>${this.escape(m.name)}</option>`).join("")}</select></div><div class="field"><label>Принтер</label><select id="printer">${this.data.printers.map(x=>`<option value="${x.id}" ${x.id===c.printerId?"selected":""}>${this.escape(x.name)}</option>`).join("")}</select></div><div class="field"><label>Вес одного изделия, г</label><input id="weight" type="number" min="0" step="0.1" value="${c.weight}"></div><div class="field"><label>Количество, шт.</label><input id="quantity" type="number" min="1" step="1" value="${q}"></div><div class="field"><label>Время, часы</label><input id="hours" type="number" min="0" step="1" value="${c.hours}"></div><div class="field"><label>Время, минуты</label><input id="minutes" type="number" min="0" max="59" step="1" value="${c.minutes}"></div><div class="field"><label>📦 Упаковка, шт.</label><input id="packagingQty" type="number" min="0" max="${q}" step="1" value="${pack}"><div class="field-hint">Ставка: ${this.money(s.costs.packaging)} / шт. Можно поставить 0.</div></div><div class="field"><label>🛠 Постобработка, шт.</label><input id="postProcessingQty" type="number" min="0" max="${q}" step="1" value="${post}"><div class="field-hint">По умолчанию = количество изделий. Можно изменить или поставить 0.</div></div><div class="field full"><div class="explain">💡 Ставки задаются в настройках за 1 изделие. Здесь указывается, для скольких изделий применять упаковку и постобработку.</div></div><div class="field full"><label>Тип клиента</label><div class="choice-grid"><div class="choice"><input type="radio" name="customerType" id="customer-retail" value="retail" ${c.customerType==="retail"?"checked":""}><label for="customer-retail"><strong>🛒 Розница</strong><span>Базовая наценка ${s.commercial.retailMarkup}%</span></label></div><div class="choice"><input type="radio" name="customerType" id="customer-regular" value="regular" ${c.customerType==="regular"?"checked":""}><label for="customer-regular"><strong>⭐ Постоянный клиент</strong><span>Скидка ${s.commercial.regularDiscount}%</span></label></div><div class="choice"><input type="radio" name="customerType" id="customer-wholesale" value="wholesale" ${c.customerType==="wholesale"?"checked":""}><label for="customer-wholesale"><strong>📦 Опт</strong><span>Скидка зависит от количества</span></label></div></div><label class="urgent-choice"><input id="urgent" type="checkbox" ${c.urgent?"checked":""}><span><b>⚡ Срочный заказ</b><br><span class="muted">Надбавка ${s.commercial.urgentMarkup}%</span></span></label></div></div></div><div class="card"><h3>Себестоимость</h3><div class="cost-list"><div class="cost-line"><span>🧵 Материал <span class="meta">(${this.money(r.materialCost/r.q)} / шт.)</span></span><b id="cost-material">${this.money(r.materialCost)}</b></div><div class="cost-line"><span>🖨 Печать <span class="meta">(${this.money(r.machineCost/r.q)} / шт.)</span></span><b id="cost-machine">${this.money(r.machineCost)}</b></div><div class="cost-line"><span>📦 Упаковка <span class="meta">(${this.money(r.packagingRate)} / шт. × ${r.packagingQty} шт.)</span></span><b id="cost-packaging">${this.money(r.packagingCost)}</b></div><div class="cost-line"><span>🛠 Постобработка <span class="meta">(${this.money(r.postProcessingRate)} / шт. × ${r.postProcessingQty} шт.)</span></span><b id="cost-post">${this.money(r.postProcessingCost)}</b></div></div><div class="cost-total"><span>Себестоимость заказа</span><span id="cost-total">${this.money(r.cost)}</span></div><div class="explain">Себестоимость — реальные затраты до наценки, скидки, срочности и минимального заказа.</div></div></div><div class="result"><div class="card result-card"><div class="price-hero"><div class="eyebrow">Итого за заказ</div><div class="price" id="sale-price">${this.money(r.salePrice)}</div><div class="per-unit" id="sale-unit-hero">${this.money(r.salePricePerUnit)} за изделие</div></div><div class="summary"><div class="box"><span>Себестоимость</span><br><b id="cost">${this.money(r.cost)}</b></div><div class="box"><span>Прибыль</span><br><b id="profit" class="profit-positive">${this.money(r.profit)}</b></div><div class="box"><span>Цена / шт.</span><br><b id="sale-unit">${this.money(r.salePricePerUnit)}</b></div><div class="box"><span>Маржа</span><br><b id="margin">${r.margin.toFixed(1)}%</b></div></div><div class="result-section"><h3>📊 Как получилась цена</h3><div class="commercial"><div class="commercial-line"><span>Цена с базовой наценкой</span><span class="value" id="commercial-base">${this.money(r.retailBasePrice)}</span></div><div class="commercial-line"><span id="commercial-discount-label">${this.escape(r.discountLabel||"Скидка")}</span><span class="value" id="commercial-discount">${r.discount?`−${this.money(r.discountAmount)}`:"0 ₽"}</span></div><div class="commercial-line"><span>⚡ Срочность</span><span class="value" id="commercial-urgent">${r.urgentMarkup?`+${r.urgentMarkup}% · ${this.money(r.urgentCost)}`:"Нет"}</span></div><div class="commercial-line"><span>Минимальный заказ</span><span class="value" id="commercial-minimum">${this.money(r.minimumOrder)}</span></div><div class="commercial-line"><span>Округление</span><span class="value">до ${this.money(s.rounding)}</span></div></div><div id="minimum-note">${r.minimumApplied?`<div class="minimum-note">ℹ️ Сработал минимальный заказ: расчётная цена была ниже ${this.money(r.minimumOrder)}.</div>`:""}</div></div><div class="result-section"><h3>📦 Заказ</h3><div class="commercial"><div class="commercial-line"><span>Количество</span><span class="value" id="order-qty">${r.q} шт.</span></div><div class="commercial-line"><span>Материал</span><span class="value">${this.escape(r.material?.name||"")}</span></div><div class="commercial-line"><span>Принтер</span><span class="value">${this.escape(r.printer?.name||"")}</span></div><div class="commercial-line"><span>Вес с учётом отходов</span><span class="value" id="order-weight">${r.totalEffectiveWeight.toFixed(1)} г</span></div></div></div><div class="actions copy-grid"><button class="primary" id="save-calc">💾 Сохранить</button><button id="print-calc">🖨 Печать / PDF</button><button id="copy-calc">📋 Полный расчёт</button><button id="copy-client-price">📄 Цена клиенту</button></div><div id="copy-status" class="notice" aria-live="polite"></div></div></div></div>`;};

p.updateResult=function(){const r=this.calculate(),set=(id,text)=>{const e=this.querySelector(`#${id}`);if(e)e.textContent=text;};set("sale-price",this.money(r.salePrice));set("sale-unit-hero",`${this.money(r.salePricePerUnit)} за изделие`);set("cost",this.money(r.cost));set("profit",this.money(r.profit));set("sale-unit",this.money(r.salePricePerUnit));set("margin",`${r.margin.toFixed(1)}%`);set("cost-material",this.money(r.materialCost));set("cost-machine",this.money(r.machineCost));set("cost-packaging",this.money(r.packagingCost));set("cost-post",this.money(r.postProcessingCost));set("cost-total",this.money(r.cost));set("commercial-base",this.money(r.retailBasePrice));set("commercial-discount",r.discount?`−${this.money(r.discountAmount)}`:"0 ₽");set("commercial-urgent",r.urgentMarkup?`+${r.urgentMarkup}% · ${this.money(r.urgentCost)}`:"Нет");set("commercial-minimum",this.money(r.minimumOrder));set("order-qty",`${r.q} шт.`);set("order-weight",`${r.totalEffectiveWeight.toFixed(1)} г`);const dl=this.querySelector("#commercial-discount-label");if(dl)dl.textContent=r.discountLabel||"Скидка";const mn=this.querySelector("#minimum-note");if(mn)mn.innerHTML=r.minimumApplied?`<div class="minimum-note">ℹ️ Сработал минимальный заказ: расчётная цена была ниже ${this.money(r.minimumOrder)}.</div>`:"";const q=Math.max(1,r.q),a=this.querySelector("#packagingQty"),b=this.querySelector("#postProcessingQty");if(a)a.max=q;if(b)b.max=q;};

p.bindCalculator=function(){["weight","quantity","hours","minutes","packagingQty","postProcessingQty"].forEach(id=>{const el=this.querySelector(`#${id}`);if(!el)return;el.addEventListener("input",()=>{this.data.calculator[id]=el.value;this.saveData();this.updateResult();});el.addEventListener("change",()=>{this.data.calculator[id]=el.value;this.saveData();this.updateResult();});});const m=this.querySelector("#material"),pr=this.querySelector("#printer"),u=this.querySelector("#urgent");m.onchange=()=>{this.data.calculator.materialId=m.value;this.saveData();this.updateResult();};pr.onchange=()=>{this.data.calculator.printerId=pr.value;this.saveData();this.updateResult();};this.querySelectorAll("input[name=customerType]").forEach(e=>e.onchange=()=>{this.data.calculator.customerType=e.value;this.saveData();this.render();});u.onchange=()=>{this.data.calculator.urgent=u.checked;this.saveData();this.updateResult();};this.querySelector("#save-calc").onclick=()=>this.saveCalculation();this.querySelector("#print-calc").onclick=()=>this.printCalculation(this.calculate());this.querySelector("#copy-calc").onclick=()=>this.copy(this.textForResult(this.calculate()));const client=this.querySelector("#copy-client-price");if(client)client.onclick=()=>this.copy(this.textForClient(this.calculate()));};

p.renderSettings=function(){const s=this.data.settings;migrate(this.data.calculator,s);const html=originalRenderSettings.call(this);return html+`<div class="settings-costs"><h3>💰 Стандартные ставки за изделие</h3><div class="hint">Здесь задаётся стоимость одной упаковки и одной операции постобработки. В калькуляторе отдельно указывается количество изделий, к которым применять ставку.</div><div class="settings-cost-grid"><div class="field"><label>📦 Упаковка, ₽ / шт.</label><input id="set-packaging" type="number" min="0" step="1" value="${s.costs.packaging}"></div><div class="field"><label>🛠 Постобработка, ₽ / шт.</label><input id="set-post-processing" type="number" min="0" step="1" value="${s.costs.postProcessing}"></div></div></div>`;};

p.bindSettings=function(){originalBindSettings.call(this);const btn=this.querySelector("#save-settings");if(!btn)return;btn.addEventListener("click",()=>{const s=this.data.settings;s.costs.packaging=Math.max(0,num(this.querySelector("#set-packaging")?.value,500));s.costs.postProcessing=Math.max(0,num(this.querySelector("#set-post-processing")?.value,300));s.costsVersion=2;delete s.costs.labor;this.saveData();this.toast("✓ Ставки сохранены");});};

p.printCalculation=function(r){const w=window.open("","_blank","width=900,height=900");if(!w){this.toast("⚠️ Разрешите всплывающие окна для печати");return;}const row=(a,b)=>`<tr><td>${a}</td><td>${b}</td></tr>`;const html=`<!doctype html><html><head><meta charset="utf-8"><title>Расчёт 3D печати</title><style>@page{size:A4;margin:15mm}*{box-sizing:border-box}body{font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Arial,sans-serif;color:#171717;font-size:11px;line-height:1.4;margin:0}.sheet{max-width:760px;margin:auto}.head{display:flex;justify-content:space-between;border-bottom:2px solid #222;padding-bottom:10px;margin-bottom:16px}.title{font-size:21px;font-weight:700}.sub{font-size:10px;color:#666}.total{text-align:right}.total .label{font-size:9px;color:#666;text-transform:uppercase}.total .value{font-size:23px;font-weight:700}.sec{margin:13px 0}.sec h2{font-size:12px;margin:0 0 6px;padding-bottom:4px;border-bottom:1px solid #ddd}.tbl{width:100%;border-collapse:collapse;font-size:10.5px}.tbl td{padding:4px;border-bottom:1px solid #eee}.tbl td:last-child{text-align:right;font-weight:600}.sum{display:grid;grid-template-columns:repeat(3,1fr);gap:7px;margin-top:10px}.box{border:1px solid #ddd;border-radius:6px;padding:7px}.box .label{font-size:8px;color:#666}.box .value{font-size:13px;font-weight:700}.foot{margin-top:16px;padding-top:7px;border-top:1px solid #ddd;font-size:8px;color:#777;text-align:center}</style></head><body><div class="sheet"><div class="head"><div><div class="title">3D Калькулятор</div><div class="sub">Расчёт стоимости заказа · ${new Date().toLocaleString("ru-RU")}</div></div><div class="total"><div class="label">Итого за заказ</div><div class="value">${this.money(r.salePrice)}</div></div></div><div class="sec"><h2>Заказ</h2><table class="tbl">${row("Материал",this.escape(r.material?.name||""))}${row("Принтер",this.escape(r.printer?.name||""))}${row("Количество",`${r.q} шт.`)}${row("Вес одного изделия",`${r.weight} г`)}${row("Вес с отходами",`${r.totalEffectiveWeight.toFixed(1)} г`)}${row("Время печати",`${Math.floor(r.totalHours)} ч ${Math.round((r.totalHours%1)*60)} мин`)}${row("Тип клиента",this.escape(r.customerType))}</table></div><div class="sec"><h2>Себестоимость</h2><table class="tbl">${row("Материал",this.money(r.materialCost))}${row("Печать",this.money(r.machineCost))}${row(`Упаковка · ${this.money(r.packagingRate)} ₽/шт. × ${r.packagingQty} шт.`,this.money(r.packagingCost))}${row(`Постобработка · ${this.money(r.postProcessingRate)} ₽/шт. × ${r.postProcessingQty} шт.`,this.money(r.postProcessingCost))}${row("Итого себестоимость",this.money(r.cost))}</table></div><div class="sum"><div class="box"><div class="label">ЦЕНА / ШТ.</div><div class="value">${this.money(r.salePricePerUnit)}</div></div><div class="box"><div class="label">ПРИБЫЛЬ</div><div class="value">${this.money(r.profit)}</div></div><div class="box"><div class="label">МАРЖА</div><div class="value">${r.margin.toFixed(1)}%</div></div></div><div class="sec"><h2>Коммерческие условия</h2><table class="tbl">${row("Базовая цена с наценкой",this.money(r.retailBasePrice))}${row(r.discountLabel||"Скидка",r.discount?`−${this.money(r.discountAmount)}`:"0 ₽")}${row("Срочность",r.urgentMarkup?`+${r.urgentMarkup}% · ${this.money(r.urgentCost)}`:"Нет")}${row("Минимальный заказ",this.money(r.minimumOrder))}${row("Округление",`до ${this.money(this.data.settings.rounding)}`)}</table></div><div class="foot">Расчёт сформирован в 3D Калькуляторе</div></div><script>window.onload=()=>setTimeout(()=>window.print(),200)</script></body></html>`;w.document.open();w.document.write(html);w.document.close();w.focus();};

